namespace IDSketcher {
static class Program {
    [STAThread] static void Main(string[] args) {
        DisplayLayout.InitializeScaling();Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
        if(args.Contains("--dpi-check")){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"dpi-check.txt"),DisplayLayout.ScalingDescription());return;}
        if(args.Contains("--boolean-test")){try{using(var studio=new Studio()){studio.TestVectorClipboardAndBooleans();studio.TestBoxDuplicateShortcuts();}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"boolean-test.txt"),"PASS");}catch(Exception error){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"boolean-test.txt"),error.ToString());}return;}if(args.Contains("--navigation-test")){try{using(var studio=new Studio())studio.TestRadiusAndNavigation();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"navigation-test.txt"),"PASS");}catch(Exception error){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"navigation-test.txt"),error.ToString());}return;}if(args.Contains("--quality-test")){try{using(var studio=new Studio())studio.TestCentredSetupAndCanvasQuality();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-test.txt"),"PASS");}catch(Exception error){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-test.txt"),error.ToString());}return;}if(args.Contains("--tools-test")){try{using(var s=new Studio()){s.TestRequestedDefaults();s.TestPencilAndPalette();s.TestRequestedChanges();s.TestVectorPenChanges();s.TestVectorWorkflow();s.TestGridAndGroups();s.TestVisibleFill();s.TestWorkspaceControls();s.TestPressureButtons();s.TestColourCursorTools();s.TestRealignAndCrossings();s.TestSelectEllipsePalette();s.TestRotationAndBrushFixes();s.TestLayerMenuPaletteRotation();s.TestLayerDragAndLargeBrushes();s.TestHighFlowPaintbrush();s.TestUppercaseUI();s.TestNamesAndColourLayout();s.TestCopyStyle();s.TestNavigationAndLens();s.TestVectorSelectionAndColourLayout();s.TestLayerSymmetryTextAndDpi();s.TestNarrowPaletteAndBoxHighlight();s.TestOpacityPolygonBrightness();s.TestStartupDpiIcons();s.TestCentredSetupAndCanvasQuality();s.TestRadiusAndNavigation();s.TestVectorClipboardAndBooleans();s.TestBoxDuplicateShortcuts();}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tools-test-results.txt"),"PASS: cached interactive zoom/pan with anchor preservation, idle sharpening and edit invalidation; editable corner radius, clamping, undo/redo, copy style and persistence; New Canvas centred over normal/maximised owner after DPI sizing; smooth enlarged pixel display with consistent partial repaint and unchanged source pixels; native vector display at fractional zoom and rotation; single numeric layer opacity caption; shape opacity percent; 3-20 polygon slider/caption/live geometry; Shift point horizontal/vertical axis lock; black-colour-white brightness endpoints and hue retention; native per-monitor sharp DPI text at 200%; centred RGB labels/values; matching stroke font; per-layer symmetry and persistence; editable vector glyph text/font/style/point size, undo/redo and save/reopen; vector Select highlight; editable mirror/radial copies and single-step undo; vector lasso/polygon selection with add/subtract; RGB/HEX/APPLY/ADD layout and matching vector fill/remove/weight row; separate non-clickable shortcut boxes; pixel V and vector F/L/O/P/C/R/E/G; Alt+G grid; Space pan/rotation; cached pan; conditional polygon sides; vector style below RGB; 30-100mm lens, undo/redo, persistence and legacy default; supersampled antialiasing; drag reorder/up/down/locks and large brush alpha equivalence; saved-colour removal, left-opening layer creation submenu, layer actions, top opacity, double-Space reset; Select/no-ink/Escape, elliptical/circular selections, saved palette persistence and bold text; double-click realignment/undo, self-crossing taper opacity, hidden cursor, executable/window icon; cursor buttons, 500px airbrush, HEX input, eyedropper, polygon selection right-click, polygon edge constraints, conditional spacing and moved weight; X/S/P pressure controls and recall, predictive percentage, fill icon and guide button removal; compact panel/equal fill widths, guide menu, vector colour controls visibility, clockwise/anticlockwise view rotation and inverse pointer mapping; visible-layer pixel/vector fill, K, selection/hidden/locked layers and undo/redo; 10mm centred grid/snapping, group pick/save/reopen/undo/redo, G shortcuts; vector Ctrl+A; all four draft tools accept on right-click/V/button with undo/redo; zero box/polygon taper; solid fill and legacy fill migration; separate import entries; vector pen click/drag/Enter/cancel, linked and Alt-broken handles, undo/redo/save/reopen; pixel pencil drawing before/after palette, all 48 swatch clicks and repeated open/close, 8x6 palette, 80% grey defaults, F full-layer/selection fill, no-op and locked fill, undo/redo, airbrush softness/build-up/order, polyline corners/Enter/persistence.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tools-test-results.txt"),"FAIL: "+ex);}return;}if(args.Contains("--ui-test")){try{var studio=new Studio();studio.PrepareInteractiveTest();Application.Run(studio);}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-error.txt"),ex.ToString());}return;}if (args.Contains("--self-test")) { Tests.Run(); return; }
        if (args.Contains("--preview")) { using(Studio s=new Studio())s.Preview(); return; }
        Application.Run(new Studio());
    }
}
// Disabled native button captions ignore ForeColor; paint guide captions explicitly.
class GuideButton : Button {
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(!Theme.Light&&!Enabled){var rect=ClientRectangle;rect.Inflate(-3,-3);using(var brush=new SolidBrush(BackColor))e.Graphics.FillRectangle(brush,rect);TextRenderer.DrawText(e.Graphics,Text,Font,rect,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}
}
static class Theme {
    static Theme(){SetLight(true);}
    public static bool Light;
    public static void SetLight(bool light){Light=light;Bg=light?Color.FromArgb(235,238,242):Color.FromArgb(29,32,38);Panel=light?Color.FromArgb(246,247,249):Color.FromArgb(39,43,51);Text=light?Color.FromArgb(31,42,55):Color.FromArgb(229,233,240);Accent=light?Color.FromArgb(55,173,154):Color.FromArgb(112,211,192);}
    public static void Apply(Control c){UppercaseUI.Apply(c);if(!c.Font.Bold)c.Font=new Font(c.Font,FontStyle.Bold);c.ForeColor=!Light&&(c.Text=="Draw on guide"||c.Text=="Reset guide"||c is NumericUpDown||c.Parent is NumericUpDown)?Color.White:Text;c.BackColor=c is Canvas?(Light?Color.FromArgb(207,214,223):Color.FromArgb(22,25,30)):c is Form||c is ListBox?Bg:Panel;if(c is TextBoxBase||c is NumericUpDown||c is ComboBox)c.BackColor=Light?Color.White:Bg;Button b=c as Button;if(b!=null)b.FlatAppearance.BorderColor=Light?Color.FromArgb(181,190,201):Color.FromArgb(67,73,85);foreach(Control child in c.Controls)Apply(child);}
    public static Color Bg = Color.FromArgb(29,32,38), Panel = Color.FromArgb(39,43,51), Text = Color.FromArgb(229,233,240), Accent = Color.FromArgb(112,211,192);
    public static Button Button(string text, EventHandler click) {
        Button b = text=="Draw on guide"||text=="Reset guide"?(Button)new GuideButton():new Button();b.Text=UppercaseUI.Caption(text);b.Height=34;b.Width=82;b.FlatStyle=FlatStyle.Flat;b.BackColor=Panel;b.ForeColor=Text;b.Margin=new Padding(3);b.Cursor=Cursors.Hand;
        b.FlatAppearance.BorderColor=Color.FromArgb(67,73,85); b.Click+=click; return b;
    }
    public static Label Label(string text, int height) { return new Label { Text=text, ForeColor=Text, Height=height, Dock=DockStyle.Top, TextAlign=ContentAlignment.MiddleLeft }; }
    public static void Form(Form f) { f.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);f.BackColor=Bg; f.ForeColor=Text; f.Font=new Font("Segoe UI",9,FontStyle.Bold); f.AutoScaleMode=AutoScaleMode.None;SharpDpi.Configure(f); f.Load+=delegate{if(!(f is Studio)){DisplayLayout.FitDialog(f,Screen.FromControl(f).WorkingArea);if(f is Setup)DisplayLayout.CentreDialog(f,f.Owner);}}; }
}
partial class Layer : IDisposable {
    public bool IsVector;public string Name; public Bitmap Image; public float Opacity=1; public bool Visible=true;
    public Layer(string name,int w,int h) { Name=name; Image=new Bitmap(w,h,PixelFormat.Format32bppArgb); }
    public override string ToString() { return (Visible ? "●  " : "○  ")+Name; }
    public void Dispose() { InvalidateVectors();Image.Dispose(); }
}
partial class Document : IDisposable {
    public int Width,Height,Dpi; public string Paper; public List<Layer> Layers=new List<Layer>(); public int Active;
    public static Size Pixels(string paper,int dpi) { return new Size((int)Math.Round((paper=="A3" ? 297 : 210)/25.4*dpi),(int)Math.Round((paper=="A3" ? 420 : 297)/25.4*dpi)); }
    public static Size Pixels(string paper,int dpi,bool landscape) { Size s=Pixels(paper,dpi); return landscape ? new Size(s.Height,s.Width) : s; }
    public bool Landscape { get { return Width>Height; } }
    public Document(string paper,int dpi,bool landscape=true) { Paper=paper; Dpi=dpi; Size s=Pixels(paper,dpi,landscape); Width=s.Width; Height=s.Height; Layers.Add(new Layer("LAYER 1",Width,Height)); }
    public Document(CanvasPreset preset):this(preset.Id,preset.Dpi,preset.Width,preset.Height){CreateBaseLayers();}
    Document(string paper,int dpi,int width,int height){Paper=paper;Dpi=dpi;Width=width;Height=height;Layers.Add(new Layer("LAYER 1",width,height));}
    public Layer Selected { get { return Layers[Active]; } }
    public void Paint(Graphics g,bool fastPreview=false) {
        if(!HasBase)using (Brush b=new SolidBrush(Color.White)) g.FillRectangle(b,0,0,Width,Height);
        foreach(Layer l in Layers) if(l.Visible && l.Opacity>0) DrawLayer(g,l,fastPreview);
    }
    public static void DrawLayer(Graphics g,Layer l,bool fastPreview=false) {
        // Draw only the exposed canvas area. Applying opacity to the whole source caused expensive conversions even for a tiny repaint.
        var clip=g.VisibleClipBounds;clip.Inflate(3,3);var rect=Rectangle.Intersect(Rectangle.Ceiling(clip),new Rectangle(0,0,l.Image.Width,l.Image.Height));if(rect.Width<=0||rect.Height<=0)return;if(!fastPreview)rect=new Rectangle(0,0,l.Image.Width,l.Image.Height);
        if(l.Opacity>=1){g.DrawImage(l.Rendered(),rect,rect,GraphicsUnit.Pixel);return;}
        using(ImageAttributes attr=new ImageAttributes()) { ColorMatrix m=new ColorMatrix(); m.Matrix33=l.Opacity; attr.SetColorMatrix(m); g.DrawImage(l.Rendered(),rect,rect.X,rect.Y,rect.Width,rect.Height,GraphicsUnit.Pixel,attr); }
    }
    public Bitmap Flatten() { Set3DQuality(true);try{Bitmap b=new Bitmap(Width,Height,PixelFormat.Format32bppArgb); b.SetResolution(Dpi,Dpi); using(Graphics g=Graphics.FromImage(b)) Paint(g); return b;}finally{Set3DQuality(false);} }
    public static byte[] Png(Bitmap b) { using(MemoryStream s=new MemoryStream()) { b.Save(s,ImageFormat.Png); return s.ToArray(); } }
    public static Bitmap Decode(byte[] bytes) { using(MemoryStream s=new MemoryStream(bytes)) using(Bitmap source=new Bitmap(s)) { Bitmap b=new Bitmap(source.Width,source.Height,PixelFormat.Format32bppArgb); b.SetResolution(source.HorizontalResolution,source.VerticalResolution);using(Graphics g=Graphics.FromImage(b)) { g.CompositingMode=CompositingMode.SourceCopy; g.DrawImageUnscaled(source,0,0); } return b; } }
    public void Save(string path) {
        string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";
        try { using(BinaryWriter w=new BinaryWriter(File.Create(temp))) { w.Write("IDSKETCHER14"); w.Write(Paper); w.Write(Dpi); w.Write(Width); w.Write(Height); w.Write(Active); w.Write(Layers.Count); foreach(Layer l in Layers) { w.Write(l.Name); w.Write(l.Opacity); w.Write(l.Visible);w.Write(l.IsVector); byte[] p=Png(l.Image); w.Write(p.Length); w.Write(p);w.Write(l.Vectors.Count);foreach(var shape in l.Vectors){shape.Write(w);shape.Fill.Write(w);w.Write(shape.GroupId);shape.WriteText(w);w.Write(shape.CornerRadius);shape.WriteContours(w);}l.Adjustment.Write(w);w.Write(l.Locked);w.Write(l.PermanentlyLocked);w.Write(l.Is3D);if(l.Is3D)l.Scene.Write(w);l.WriteSymmetry(w); } }
            if(File.Exists(path)) File.Replace(temp,path,null); else File.Move(temp,path);
        } finally { if(File.Exists(temp)) File.Delete(temp); }
    }
    public static Document Load(string path) {
        Document d=null;
        try { using(BinaryReader r=new BinaryReader(File.OpenRead(path))) {
            string signature=r.ReadString();int version;if(!signature.StartsWith("IDSKETCHER")||!int.TryParse(signature.Substring(10),out version)||version<1||version>14)throw new InvalidDataException("This is not an IDeaSKETCHER project.");
            string paper=r.ReadString(); int dpi=r.ReadInt32(), width=r.ReadInt32(), height=r.ReadInt32(), active=r.ReadInt32(), count=r.ReadInt32();
            if(!CanvasPreset.Valid(paper,dpi,width,height) || count<1 || count>64 || active<0 || active>=count) throw new InvalidDataException("Invalid project settings.");
            d=new Document(paper,dpi,width,height); d.Layers[0].Dispose(); d.Layers.Clear();
            for(int i=0;i<count;i++) { string name=r.ReadString(); float opacity=r.ReadSingle(); bool visible=r.ReadBoolean();bool isVector=version>=3&&r.ReadBoolean(); int n=r.ReadInt32(); if(name.Length>200 || float.IsNaN(opacity) || opacity<0 || opacity>1 || n<1 || n>200000000 || n>r.BaseStream.Length-r.BaseStream.Position) throw new InvalidDataException("Invalid layer data.");
                Bitmap b=Decode(r.ReadBytes(n)); if(b.Width!=width || b.Height!=height) { b.Dispose(); throw new InvalidDataException("Invalid layer size."); }
                Layer l=new Layer(name,1,1); l.Image.Dispose(); l.Image=b; l.Opacity=opacity; l.Visible=visible;l.IsVector=isVector; d.Layers.Add(l);if(signature!="IDSKETCHER1"){int shapes=r.ReadInt32();if(shapes<0||shapes>10000)throw new InvalidDataException("Invalid vector count");for(int v=0;v<shapes;v++){var shape=VectorShape.Read(r,version>=3,version>=4,version>=6);if(version>=8)shape.Fill=VectorFillStyle.Read(r);if(version>=10){shape.GroupId=r.ReadString();if(shape.GroupId.Length>64)throw new InvalidDataException("Invalid vector group");}if(version>=12)shape.ReadText(r);if(version>=13){shape.CornerRadius=r.ReadSingle();if(float.IsNaN(shape.CornerRadius)||shape.CornerRadius<0||shape.CornerRadius>500)throw new InvalidDataException("Invalid corner radius.");}if(version>=14)shape.ReadContours(r);l.Vectors.Add(shape);}}if(version>=5)l.Adjustment=LayerAdjustment.Read(r);if(version>=7){l.Locked=r.ReadBoolean();l.PermanentlyLocked=r.ReadBoolean();if(l.PermanentlyLocked){if(i!=0||l.IsVector)throw new InvalidDataException("Invalid permanent base layer");l.Locked=true;}}if(version>=9&&r.ReadBoolean()){if(l.IsVector||l.PermanentlyLocked)throw new InvalidDataException("Invalid 3D layer type.");l.Scene=ThreeDView.Read(r,version>=11);}if(version>=12)l.ReadSymmetry(r);
            } d.Active=active;if(signature=="IDSKETCHER2")d.SplitLegacyLayers(); return d;
        }} catch { if(d!=null) d.Dispose(); throw; }
    }
    public void Dispose() { foreach(Layer l in Layers) l.Dispose(); }
}
