// Distance-based filtering removes mouse jitter consistently across event rates.
// Work in canvas pixels, scaling the smoothing distance by zoom for a stable feel.
class StrokeSmoother {
    PointF raw,filtered; readonly float distance; readonly Action<PointF> emit;
    public StrokeSmoother(PointF start,int strength,float zoom,Action<PointF> output) {
        raw=filtered=start; distance=30f*(strength/100f)*(strength/100f)/Math.Max(.02f,zoom); emit=output;
    }
    public void Move(PointF point) {
        double dx=point.X-raw.X,dy=point.Y-raw.Y,length=Math.Sqrt(dx*dx+dy*dy);
        if(length<.0001)return;
        if(distance==0) { raw=filtered=point; emit(point); return; }
        int count=Math.Max(1,(int)Math.Ceiling(length/Math.Max(.25f,distance/10)));
        double alpha=1-Math.Exp(-length/count/distance);
        for(int i=1;i<=count;i++) {
            PointF target=new PointF(raw.X+(float)(dx*i/count),raw.Y+(float)(dy*i/count));
            filtered=new PointF(filtered.X+(float)((target.X-filtered.X)*alpha),filtered.Y+(float)((target.Y-filtered.Y)*alpha)); emit(filtered);
        }
        raw=point;
    }
    public void Finish() { if(filtered!=raw) { filtered=raw; emit(raw); } }
}
class Wheel : Control {
    Bitmap disk; public double Hue=210,Saturation=.3,Value=.25; public Action Changed;
    public Wheel() { Size=new Size(200,200); DoubleBuffered=true; Cursor=Cursors.Cross;SetStyle(ControlStyles.Selectable,true); }
    public static Color Hsv(double h,double s,double v) { double c=v*s,x=c*(1-Math.Abs(h/60%2-1)),m=v-c; double r=0,g=0,b=0; if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;} return Color.FromArgb((int)Math.Round((r+m)*255),(int)Math.Round((g+m)*255),(int)Math.Round((b+m)*255)); }
    public Color Selected { get { return Hsv(Hue,Saturation,Value); } }
    public void SetColor(Color c) { Hue=c.GetHue(); double max=Math.Max(c.R,Math.Max(c.G,c.B)),min=Math.Min(c.R,Math.Min(c.G,c.B)); Saturation=max==0?0:(max-min)/max; Value=max/255; Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) { base.OnPaint(e); int n=Math.Min(Width,Height); if(disk==null||disk.Width!=n) { if(disk!=null)disk.Dispose(); disk=new Bitmap(n,n); double radius=n/2.0-4; for(int y=0;y<n;y++)for(int x=0;x<n;x++) { double dx=x-n/2.0,dy=y-n/2.0,s=Math.Sqrt(dx*dx+dy*dy)/radius; if(s<=1)disk.SetPixel(x,y,Hsv((Math.Atan2(dy,dx)*180/Math.PI+360)%360,s,1)); } } e.Graphics.DrawImageUnscaled(disk,0,0); double a=Hue*Math.PI/180; float px=n/2+(float)(Math.Cos(a)*Saturation*(n/2-4)),py=n/2+(float)(Math.Sin(a)*Saturation*(n/2-4)); e.Graphics.SmoothingMode=SmoothingMode.AntiAlias; using(Pen p=new Pen(Color.Black,3))e.Graphics.DrawEllipse(p,px-5,py-5,10,10); using(Pen p=new Pen(Color.White,1.5f))e.Graphics.DrawEllipse(p,px-5,py-5,10,10); }
    void Pick(MouseEventArgs e) { double n=Math.Min(Width,Height),dx=e.X-n/2,dy=e.Y-n/2; Hue=(Math.Atan2(dy,dx)*180/Math.PI+360)%360; Saturation=Math.Min(1,Math.Sqrt(dx*dx+dy*dy)/(n/2-4));Value=1; Invalidate(); if(Changed!=null)Changed(); }
    protected override void OnMouseDown(MouseEventArgs e) { if(e.Button==MouseButtons.Left){Focus();Capture=true;Pick(e);}base.OnMouseDown(e); }
    public void TestPick(Point point){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,point.X,point.Y,0));}
    protected override void OnMouseMove(MouseEventArgs e) { if(Capture)Pick(e);base.OnMouseMove(e); }
    protected override void OnMouseUp(MouseEventArgs e) { Capture=false;base.OnMouseUp(e); }
    protected override void Dispose(bool disposing) { if(disposing&&disk!=null)disk.Dispose();base.Dispose(disposing); }
}
