class HistoryItem { public ThreeDView Scene; public LayerAdjustment Adjustment; public byte[] Selection; public Layer Layer;public List<VectorShape> Vectors; public byte[] Pixels; public int Width,Height;
    public static byte[] Capture(Bitmap image){var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var bytes=new byte[image.Width*image.Height*4];for(int y=0;y<image.Height;y++)Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),bytes,y*image.Width*4,image.Width*4);return bytes;}finally{image.UnlockBits(data);}}
    public Bitmap Restore(){var b=new Bitmap(Width,Height,PixelFormat.Format32bppArgb);var data=b.LockBits(new Rectangle(0,0,Width,Height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{for(int y=0;y<Height;y++)Marshal.Copy(Pixels,y*Width*4,IntPtr.Add(data.Scan0,y*data.Stride),Width*4);}finally{b.UnlockBits(data);}return b;}
}
