    void UpdateStatus(){Document d=canvas.Doc;if(d==null)return;Text="IDeaSKETCHER — "+(projectPath==null?"Untitled":Path.GetFileNameWithoutExtension(projectPath))+(dirty?" *":"");status.Text=(canvas.ShowGrid?"Grid 10 mm · ":"")+(canvas.SnapToGrid?"Snap ON · ":"")+d.Paper+"  /  "+d.Dpi+" DPI     "+d.Width+" × "+d.Height+" px     "+Math.Round(canvas.Zoom*100)+"%     "+(d.Selected.Is3D?"3D · "+(canvas.Move3D?"Move":"Orbit"):d.Selected.IsVector?"Vector · "+canvas.VectorMode:canvas.FillTool?"Fill bucket":canvas.Tool)+(canvas.PressureMode=="Wacom pressure"?"     "+canvas.PenStatus:"");}
