    void Error(Exception ex){MessageBox.Show(this,ex.Message,"IDeaSKETCHER",MessageBoxButtons.OK,MessageBoxIcon.Error);}
    void AddLayer(){AddTypedLayer(false);}
    void AddTypedLayer(bool vector){if(canvas.Doc==null)return;if(canvas.Doc.Layers.Count>=32){MessageBox.Show("This MVP supports up to 32 layers.");return;}Document d=canvas.Doc;d.Layers.Insert(d.Active+1,new Layer((vector?"VECTOR ":"LAYER ")+(d.Layers.Count+1),d.Width,d.Height){IsVector=vector});d.Active++;Changed();RefreshLayers();}
    void DeleteLayer(){Document d=canvas.Doc;if(d==null||d.Layers.Count==1||d.Selected.IsLocked)return;if(MessageBox.Show(this,"Delete “"+d.Selected.Name+"”? This cannot be undone.","Delete layer",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;Layer l=d.Selected;undo.RemoveAll(x=>x.Layer==l);redo.RemoveAll(x=>x.Layer==l);d.Layers.Remove(l);l.Dispose();d.Active=Math.Min(d.Active,d.Layers.Count-1);Changed();RefreshLayers();}
    void MoveLayer(int step){Document d=canvas.Doc;if(d==null||d.Selected.IsLocked)return;int n=d.Active+step;if(n<0||n>=d.Layers.Count||d.Layers[n].PermanentlyLocked)return;Layer l=d.Selected;d.Layers.RemoveAt(d.Active);d.Layers.Insert(n,l);d.Active=n;Changed();RefreshLayers();}
    void RenameLayer(){if(canvas.Doc==null||canvas.Doc.Selected.IsLocked)return;using(Form f=new Form{Text="Rename layer",ClientSize=new Size(310,115),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false}){Theme.Form(f);TextBox t=new TextBox{Text=canvas.Doc.Selected.Name,Left=16,Top=16,Width=277,MaxLength=80};Button b=Theme.Button("Rename",delegate{if(t.Text.Trim().Length>0)f.DialogResult=DialogResult.OK;});b.SetBounds(203,60,90,34);f.Controls.Add(t);f.Controls.Add(b);f.AcceptButton=b;if(f.ShowDialog(this)==DialogResult.OK){canvas.Doc.Selected.Name=t.Text.Trim();Changed();RefreshLayers();}}}
    void Push(List<HistoryItem> list,Layer l){list.Add(new HistoryItem{Scene=l.Scene==null?null:l.Scene.Copy(),Adjustment=l.Adjustment.Copy(),Selection=canvas.CaptureSelection(),Layer=l,Vectors=l.CopyVectors(),Width=l.Image.Width,Height=l.Image.Height,Pixels=l.IsRaster?HistoryItem.Capture(l.Image):null});long bytes=list.Sum(x=>(long)(x.Pixels==null?0:x.Pixels.Length)+x.Vectors.Sum(v=>(long)v.Points.Count*8+64));while(list.Count>1&&(list.Count>24||bytes>128*1024*1024)){bytes-=(list[0].Pixels==null?0:list[0].Pixels.Length)+list[0].Vectors.Sum(v=>(long)v.Points.Count*8+64);list.RemoveAt(0);}}
    void Travel(List<HistoryItem> from,List<HistoryItem> to){canvas.EndStroke();if(from.Count==0||from[from.Count-1].Layer.IsLocked)return;HistoryItem item=from[from.Count-1];from.RemoveAt(from.Count-1);Push(to,item.Layer);if(item.Pixels!=null){Bitmap replacement=item.Restore();item.Layer.Image.Dispose();item.Layer.Image=replacement;}item.Layer.Scene=item.Scene==null?null:item.Scene.Copy();item.Layer.Adjustment=item.Adjustment.Copy();item.Layer.Vectors=item.Vectors;item.Layer.InvalidateVectors();canvas.CancelVector();canvas.Doc.Active=canvas.Doc.Layers.IndexOf(item.Layer);canvas.RestoreSelection(item.Selection);Changed();RefreshLayers();}
    void SyncColour(){if(mode.SelectedIndex<0)return;syncing=true;Color c=canvas.Ink;UpdateColourEntry();swatch.BackColor=c;value.SetColor(canvas.Ink);foreach(Control ctl in channels.Controls.Cast<Control>().ToArray())ctl.Dispose();channels.Controls.Clear();
        if(mode.Text=="HEX"){TextBox t=new TextBox{Text="#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2"),Width=210};Action apply=delegate{if(syncing)return;try{string s=t.Text.Trim().TrimStart('#');if(s.Length!=6)throw new FormatException();int n=Convert.ToInt32(s,16);canvas.Ink=Color.FromArgb((n>>16)&255,(n>>8)&255,n&255);wheel.SetColor(canvas.Ink);swatch.BackColor=canvas.Ink;UpdateColourEntry();syncing=true;value.SetColor(canvas.Ink);syncing=false;t.BackColor=SystemColors.Window;}catch{t.BackColor=Color.MistyRose;}};t.Leave+=delegate{apply();};t.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Enter){apply();e.SuppressKeyPress=true;}};channels.Controls.Add(t);channels.Controls.Add(new Label{Text="Enter a six-digit hex colour.",Width=215,Height=25});}
        else {bool hsv=mode.Text=="HSV";string[] labels=hsv?new[]{"H","S","V"}:new[]{"R","G","B"};double max=Math.Max(c.R,Math.Max(c.G,c.B))/255.0;decimal[] vals=hsv?new[]{(decimal)c.GetHue(),(decimal)(max==0?0:(max-Math.Min(c.R,Math.Min(c.G,c.B))/255.0)/max*100),(decimal)(max*100)}:new[]{(decimal)c.R,(decimal)c.G,(decimal)c.B};List<NumericUpDown> fields=new List<NumericUpDown>();for(int i=0;i<labels.Length;i++){Panel p=new Panel{Width=56,Height=30,Margin=new Padding(1)};p.Controls.Add(new Label{Text=labels[i],Width=14,Height=24,Top=0,TextAlign=ContentAlignment.MiddleCenter});NumericUpDown n=new NumericUpDown{Font=opacity.Font,Left=14,Width=40,Maximum=hsv?(i==0?360:100):255,DecimalPlaces=hsv?1:0,Value=Math.Round(vals[i],hsv?1:0)};p.Controls.Add(n);fields.Add(n);channels.Controls.Add(p);}
            foreach(NumericUpDown n in fields)n.ValueChanged+=delegate{if(syncing)return;Color next;if(hsv)next=Wheel.Hsv((double)fields[0].Value%360,(double)fields[1].Value/100,(double)fields[2].Value/100);else next=Color.FromArgb((int)fields[0].Value,(int)fields[1].Value,(int)fields[2].Value);canvas.Ink=next;wheel.SetColor(next);swatch.BackColor=next;UpdateColourEntry();syncing=true;value.SetColor(canvas.Ink);syncing=false;};
        }foreach(Control field in channels.Controls){field.Scale(new SizeF(SharpDpi.Factor(this),SharpDpi.Factor(this)));var letter=field.Controls.OfType<Label>().FirstOrDefault();var number=field.Controls.OfType<NumericUpDown>().FirstOrDefault();if(letter!=null&&number!=null){letter.Top=number.Top;letter.Height=number.Height;}}syncing=false;
    }
    protected override bool ProcessCmdKey(ref Message msg,Keys key){if(key==(Keys.Control|Keys.S)){Save(false);return true;}if(key==(Keys.Control|Keys.Shift|Keys.S)){Save(true);return true;}if(key==(Keys.Control|Keys.O)){Open();return true;}if(key==(Keys.Control|Keys.N)){NewDocument();return true;}
        if(HandleVectorClipboardKeys(key))return true;if(HandleTransformKeys(key))return true;if(HandleSelectionKeys(key))return true;if(key==Keys.Escape){canvas.EyedropperActive=false;canvas.CancelVector();canvas.SetSelectionMode("Draw");canvas.ResetShift();guideMode.SelectedItem="Freehand";if(canvas.Doc!=null&&canvas.Doc.Selected.IsRaster){canvas.ClearSelection();SelectTool("Select");}return true;}if(key==Keys.Tab&&canvas.Doc!=null&&canvas.Doc.Selected.IsRaster&&!(ActiveControl is TextBoxBase)&&!(ActiveControl is NumericUpDown)){if(canvas.Guide=="Freehand"){guideMode.SelectedItem=lastGuide;editGuide.Checked=true;}else editGuide.Checked=!editGuide.Checked;canvas.Focus();return true;}if(key==Keys.Enter&&canvas.Focused&&(canvas.VectorMode=="Polygon"||canvas.VectorMode=="Curvature pen"||canvas.VectorMode=="Polyline"||canvas.VectorMode=="Vector pen")){canvas.FinishVector();return true;}if(key==Keys.Delete&&canvas.Focused&&canvas.VectorMode=="Select/edit"){canvas.DeleteVector();return true;}if(ActiveControl is TextBoxBase||ActiveControl is NumericUpDown)return base.ProcessCmdKey(ref msg,key);
        if(key==(Keys.Alt|Keys.G)){canvas.ShowGrid=!canvas.ShowGrid;canvas.Invalidate();UpdateStatus();return true;}if(key==(Keys.Shift|Keys.G)){canvas.SnapToGrid=!canvas.SnapToGrid;UpdateStatus();return true;}if(key==(Keys.Control|Keys.G)){canvas.GroupSelectedVectors(false);return true;}if(key==(Keys.Control|Keys.Z)){Travel(undo,redo);return true;}if(key==(Keys.Control|Keys.Y)||key==(Keys.Control|Keys.Shift|Keys.Z)){Travel(redo,undo);return true;}if(key==(Keys.Control|Keys.A)&&canvas.Doc!=null&&canvas.Doc.Selected.IsVector){vectorMode.SelectedItem="Select/edit";canvas.SelectAllVectors();return true;}if(key==Keys.V&&canvas.Doc!=null&&canvas.Doc.Selected.IsVector){vectorMode.SelectedItem="Select/edit";canvas.SetSelectionMode("Draw");UpdateVectorButtons();UpdateSelectionButtons();return true;}if(canvas.Doc!=null&&canvas.Doc.Selected.IsVector){string tool=VectorShortcut(key);if(tool!=null){vectorMode.SelectedItem=tool;canvas.Focus();return true;}}if(key==Keys.V&&canvas.Doc!=null&&canvas.Doc.Selected.IsRaster){SelectTool("Select");return true;}if(key==Keys.P){SelectTool(canvas.Tool=="Pencil"?"Paintbrush":"Pencil");return true;}if(key==Keys.N){SelectTool("Pen");return true;}if(key==Keys.I){SelectTool("Ink Pen");return true;}if(key==Keys.A){SelectTool("Airbrush");return true;}if(key==Keys.M){SelectTool("Marker");return true;}if(key==Keys.K){SelectFillBucket();return true;}if(key==Keys.F){canvas.EndStroke();canvas.FillSelectionColour();return true;}if(key==Keys.E){SelectTool("Eraser");return true;}if(key==Keys.OemOpenBrackets){if(canvas.Doc!=null&&canvas.Doc.Selected.IsVector)return true;size.Value=Math.Max(size.Minimum,size.Value-1);return true;}if(key==Keys.OemCloseBrackets){if(canvas.Doc!=null&&canvas.Doc.Selected.IsVector)return true;size.Value=Math.Min(size.Maximum,size.Value+1);return true;}return base.ProcessCmdKey(ref msg,key);
    }
    protected override void Dispose(bool disposing){if(disposing)DisposeDisplayLayout();if(disposing&&addLayerMenu!=null)addLayerMenu.Dispose();if(disposing&&layerMenu!=null)layerMenu.Dispose();if(disposing&&brushPopup!=null)brushPopup.Dispose();if(disposing&&canvas.Doc!=null)canvas.Doc.Dispose();base.Dispose(disposing);}
}
