        try{for(int i=0;i<11;i++){
            var preset=CanvasPreset.All[i];Check(preset.Width==sizes[i,0]&&preset.Height==sizes[i,1]&&preset.Dpi==150,"Exact preset dimensions and DPI");
            using(var doc=new Document(preset)){doc.Selected.Image.SetPixel(10,10,Color.Red);doc.Save(path);using(var loaded=Document.Load(path)){Check(loaded.Width==preset.Width&&loaded.Height==preset.Height&&loaded.Dpi==preset.Dpi&&loaded.Paper==preset.Id&&loaded.Selected.Image.GetPixel(10,10).ToArgb()==Color.Red.ToArgb(),"Preset save/load");}using(var flat=doc.Flatten())Check(Math.Abs(flat.HorizontalResolution-preset.Dpi)<.1,"Export DPI");}
        }}finally{if(File.Exists(path))File.Delete(path);}
        Check(!CanvasPreset.Valid("AI 3:2 1K",100,1248,832)&&!CanvasPreset.Valid("unknown",300,1248,832),"Invalid preset rejection");results.Add("PASS: all 11 presets, exact dimensions, DPI, project round trips and export resolution");
    }

