        foreach(string paper in new[]{"A4","A3"})foreach(int dpi in new[]{100,150,300}){Size portrait=Document.Pixels(paper,dpi,false),landscape=Document.Pixels(paper,dpi,true);Check(portrait.Width==landscape.Height&&portrait.Height==landscape.Width,"Orientation dimensions");}
        using(Setup setup=new Setup()){Check(setup.Landscape,"Landscape startup default");Check(setup.Dpi==150&&setup.Paper=="A3","A3 print startup default");for(int i=0;i<CanvasPreset.All.Length;i++){setup.SelectPreset(i);Check(setup.Preset==CanvasPreset.All[i],"Preset selection");}}
