        results.Add("PASS: legacy canvas orientations, preset selection, landscape default and portrait project compatibility");
        List<PointF> filtered=new List<PointF>(),unfiltered=new List<PointF>();StrokeSmoother smooth=new StrokeSmoother(new PointF(0,50),80,1,filtered.Add),direct=new StrokeSmoother(new PointF(0,50),0,1,unfiltered.Add);
        for(int x=1;x<=100;x++){PointF p=new PointF(x,50+(x%2==0?5:-5));smooth.Move(p);direct.Move(p);}
        Check(filtered.Where(p=>p.X>20).Average(p=>Math.Abs(p.Y-50))<1.5,"Smoothing should reduce alternating jitter");Check(unfiltered.Count==100&&unfiltered[0]==new PointF(1,45),"Zero smoothing preserves raw input");smooth.Finish();Check(filtered.Last()==new PointF(100,55),"Smoothing reaches release point");
